// Filter to last 24h and limit to 5 items
const cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000);
const items = $input.all();
const recent = items.filter(item => {
  const pubDate = item.json.pubDate || item.json.isoDate || item.json.date;
  if (!pubDate) return true;
  return new Date(pubDate) >= cutoff;
}).slice(0, 5);
return recent.length > 0 ? recent : [{ json: { _empty: true } }];

const gh = $json;
const currentData = JSON.parse(Buffer.from(gh.content, 'base64').toString('utf-8'));
currentData.meta.lastUpdated = new Date().toISOString();
currentData.meta.updatedBy = 'n8n';
const encoded = Buffer.from(JSON.stringify(currentData, null, 2)).toString('base64');
return [{ json: { encoded: encoded, sha: gh.sha, message: 'auto: verified current — no feed items' } }];

const art = $json;
const title = art.title || '';
const desc = art.contentSnippet || art.description || '';
const url = art.link || '';
const pubDate = art.pubDate || art.isoDate || '';
const relevanceSystem = 'You are an eIPP program analyst. Determine if the given article is relevant to the FAA eIPP (eVTOL Integration Pilot Program) announced March 9, 2026. The program has 8 projects involving: Archer Aviation, Beta Technologies, Electra, Joby Aviation, Wisk Aero, Elroy Air, Reliable Robotics, Ampaire, and sponsors: Port Authority of NY/NJ, Texas DOT, Utah DOT, PennDOT/NASAO, Louisiana, Florida DOT, NC DOT, City of Albuquerque.

Respond with ONLY a JSON object:
{
  "relevant": true/false,
  "confidence": 0.0-1.0,
  "projectIds": [list of affected project IDs 1-8],
  "updateType": "milestone|otaStatus|notes|links|meta",
  "summary": "One sentence summary"
}';
const body = { model: 'claude-haiku-4-5-20251001', max_tokens: 300, system: relevanceSystem, messages: [{ role: 'user', content: 'Title: ' + title + '
Description: ' + desc + '
URL: ' + url + '
Date: ' + pubDate }] };
return [{ json: { body: body, art: { title: title, desc: desc, url: url, pubDate: pubDate } } }];

// Parse Relevance (fixed Oct 22, 2026). A deterministic gate runs after the model: an item is relevant only if its own
// title or snippet names the program or one of the eight projects. Company and stock news that never mentions the
// program (it filled the cards with Archer share-price and funding items) is dropped here, whatever the model said.
const art = $('Build Relevance Request').item.json.art;
const txt = ($json.content && $json.content[0] && $json.content[0].text) || '';
let rel = { relevant: false, confidence: 0 };
try { const m = txt.match(/\{[\s\S]*\}/); rel = JSON.parse(m[0]); } catch (e) {}
const text = (art.title || '') + ' ' + (art.desc || '');
const PROGRAM = /\beIPP\b|eVTOL Integration Pilot|Integration Pilot Program|Project Nexus|\buFLY\b|eLIFT|LIFTOff Louisiana|Multistate Collaborative/i;
const gatePassed = PROGRAM.test(text);
return [{ json: { title: art.title, desc: art.desc, url: art.url, pubDate: art.pubDate,
  relevant: !!rel.relevant && gatePassed, confidence: rel.confidence || 0, projectIds: rel.projectIds || [],
  summary: rel.summary || '', gatePassed: gatePassed } }];

// Build Extract Request (fixed Oct 22, 2026, date rule added Oct 23). The model now sees every project with its sponsor, states and project
// name. Before, the list was cut at 500 characters, so it saw two or three projects and guessed the rest, which is how
// Albuquerque news landed on Florida's card and a Wisk vertiport on Louisiana's.
const rel = $('Parse Relevance').item.json;
const gh = $json;
const currentData = JSON.parse(Buffer.from(gh.content, 'base64').toString('utf-8'));
const projectSummary = JSON.stringify(currentData.projects.map(function (p) {
  return { id: p.id, sponsor: p.sponsor, region: p.region, states: p.states, milestone: p.milestone };
}));
const extractSystem = 'You update the LAE FAA eIPP tracker. Given one news item and the eight projects, decide which ONE project the item is about and what changed.

Return ONLY a JSON object:
{
  "projectId": N or null,
  "updates": { "milestone": "one dated sentence, under 200 characters, or null", "otaStatus": "string or null" },
  "description": "What changed, one sentence, for the history log"
}

Rules: choose a project only if the item names its sponsor, its project name or a place in its states AND describes something that happened under the eIPP (a flight, an agreement, a launch, a selection). Company funding, stock prices, aircraft programs outside the eIPP and general industry news are not milestones: return projectId null. Never move news about one project onto another. Write the date the event itself happened, as the item states it. Never use the item's publication date as the event date. If the item does not say when the event happened, or it reports an event that the project's current milestone already records, return milestone null. Be conservative.';
const userMessage = 'Item title: ' + rel.title + '
Item snippet: ' + rel.desc + '
Item URL: ' + rel.url + '
Item date: ' + rel.pubDate + '
Relevance summary: ' + rel.summary + '
Projects the relevance step named: ' + JSON.stringify(rel.projectIds) + '

Projects: ' + projectSummary;
const body = { model: 'claude-haiku-4-5-20251001', max_tokens: 600, system: extractSystem, messages: [{ role: 'user', content: userMessage }] };
return [{ json: { body: body, sha: gh.sha, currentData: currentData, url: rel.url, title: rel.title, desc: rel.desc, pubDate: rel.pubDate, relIds: rel.projectIds } }];

// Apply Update (fixed Oct 22, 2026). An update reaches a project card only if (1) the model chose that project,
// (2) the relevance step also named it, and (3) the item's own title or snippet names that project's sponsor, project
// name or one of its states. Otherwise nothing on the cards changes and the item is logged as a lead, not applied.
// Notes, links and the banner are no longer written automatically: they are edited from the LAE Ecosystem Survey.
const src = $('Build Extract Request').item.json;
const currentData = src.currentData;
const txt = ($json.content && $json.content[0] && $json.content[0].text) || '';
let update = {};
try { const m = txt.match(/\{[\s\S]*\}/); update = JSON.parse(m[0]); } catch (e) {}
const NAMES = { 1: /Port Authority|Manhattan|New York|New Jersey|\bJFK\b|LaGuardia|Newark|Vermont|Delaware/i,
  2: /TxDOT|Texas Department of Transportation|Project Nexus|Texas|Fort Worth|Dallas|Houston|Austin|San Antonio/i,
  3: /UDOT|Utah|uFLY|Salt Lake|Cedar City|Idaho|Arizona|Oregon|Portland|Oklahoma City/i,
  4: /PennDOT|Pennsylvania|Multistate Collaborative|NASAO|United Therapeutics|Philadelphia|Virginia|Maryland/i,
  5: /Louisiana|DOTD|LIFTOff|Houma|Bristow|Elroy|Gulf/i,
  6: /Florida|FDOT|SunTrax|Orlando|Tampa|Miami/i,
  7: /North Carolina|NCDOT|eLIFT|Raleigh|Charlotte/i,
  8: /Albuquerque|New Mexico|Reliable Robotics|Sunport|Santa Fe|Durango/i };
const text = (src.title || '') + ' ' + (src.desc || '');
const pid = update.projectId;
const relIds = (src.relIds || []).map(Number);
const ok = !!pid && relIds.indexOf(Number(pid)) > -1 && NAMES[pid] && NAMES[pid].test(text);
// Date guard (Oct 23, 2026): a milestone must carry an event date that is earlier than the item's publication day and later
// than the newest date already on the card. That stops a re-report of a known event, dated by its publication, from replacing
// a better milestone (Aviation Week's Oct 23 report of Albuquerque's Oct 19 flights did exactly that).
const MON = { January: 0, February: 1, March: 2, April: 3, May: 4, June: 5, July: 6, August: 7, September: 8, October: 9, November: 10, December: 11 };
function datesIn(s) { const out = []; const re = /(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2}),\s+(\d{4})/g; let x; while ((x = re.exec(String(s || '')))) out.push(Date.UTC(+x[3], MON[x[1]], +x[2])); return out; }
const pub = new Date(src.pubDate || ''); const pubDay = isNaN(pub.getTime()) ? null : Date.UTC(pub.getUTCFullYear(), pub.getUTCMonth(), pub.getUTCDate());
let applied = false; let reason = '';
if (ok && update.updates) {
  const project = currentData.projects.find(function (p) { return p.id === Number(pid); });
  if (project) {
    if (update.updates.milestone) {
      const nd = datesIn(update.updates.milestone), od = datesIn(project.milestone);
      if (!nd.length) reason = 'milestone has no event date';
      else if (pubDay === null) reason = 'item has no publication date';
      else if (Math.max.apply(null, nd) >= pubDay) reason = 'milestone dated on or after the day the item was published';
      else if (od.length && Math.max.apply(null, nd) <= Math.max.apply(null, od)) reason = 'card already holds a milestone as recent or newer';
      else { project.milestone = String(update.updates.milestone).slice(0, 240); applied = true; }
    }
    if (update.updates.otaStatus) { project.otaStatus = String(update.updates.otaStatus).slice(0, 60); applied = true; }
  }
}
currentData.meta.lastUpdated = new Date().toISOString();
currentData.meta.updatedBy = 'n8n';
currentData.meta.version = (currentData.meta.version || 0) + 1;
currentData.updateHistory = currentData.updateHistory || [];
currentData.updateHistory.unshift({ timestamp: new Date().toISOString(), source: 'n8n-auto-monitor',
  description: (applied ? '' : 'Lead, not applied to a card' + (reason ? ' (' + reason + ')' : '') + ': ') + (update.description || src.title || 'news item'),
  projectsAffected: applied ? [Number(pid)] : [], sourceUrl: src.url });
currentData.updateHistory = currentData.updateHistory.slice(0, 50);
const encoded = Buffer.from(JSON.stringify(currentData, null, 2)).toString('base64');
return [{ json: { encoded: encoded, sha: src.sha, message: 'auto: ' + (applied ? '' : 'lead logged: ') + (update.description || 'eIPP item') } }];
